        </section>
      )}

      {hasCalls && (
        <section aria-label='Tool calls' className='flex flex-col gap-1'>
          <h3 className='text-muted-foreground text-xs'>Tool calls</h3>
          <ul className='flex flex-col'>
            <AnimatePresence initial={false}>
              {run.calls.map((call) => (
                <motion.li
